#define MAX_STEPS 256
#define MAX_DIST 100.0
#define SURF_DIST 0.001
#define AA 2

float getDist(vec3 p);
float rayMarch(vec3 ro, vec3 rd);
vec3 getNormal(vec3 p);
vec3 getCameraPosition();
mat3 getCameraMatrix(vec3 ro, vec3 lookAt);

float pattern1(vec3 p) {
    float t = iTime * 0.5;

    float r = length(p);
    float theta = atan(p.z, p.x) + t;
    float phi = acos(p.y/r);

    float petals = 6.0;
    float radius = 0.5 + 0.5 * sin(petals * theta + t) * sin(petals * phi);
    radius += 0.1 * sin(petals * 2.0 * theta) * sin(petals * 2.0 * phi);
    radius += 0.05 * sin(petals * 4.0 * theta - t) * sin(petals * 4.0 * phi);

    return smoothstep(0.35, 0.45, radius - r);
}

float pattern2(vec3 p) {
    float t = iTime * 0.3;

    float r = length(p);
    float theta = atan(p.z, p.x) + t;
    float phi = acos(p.y/r);

    float petals = 8.0;
    float radius = 0.5 + 0.5 * cos(petals * theta + t) * sin(petals * phi);
    radius += 0.1 * cos(petals * 2.0 * theta) * sin(petals * 2.0 * phi);
    radius += 0.05 * cos(petals * 4.0 * theta - t) * sin(petals * 4.0 * phi);

    return smoothstep(0.25, 0.35, radius - r);
}

float getDist(vec3 p) {
    float d1 = pattern1(p);
    float d2 = pattern2(p);
    return 1.0 - (d1 + d2);
}

float rayMarch(vec3 ro, vec3 rd) {
    float dO = 0.0;

    for(int i = 0; i < MAX_STEPS; i++) {
        vec3 p = ro + rd * dO;
        float dS = getDist(p);
        dO += dS;
        if(dO > MAX_DIST || abs(dS) < SURF_DIST) break;
    }

    return dO;
}

vec3 getNormal(vec3 p) {
    float d = getDist(p);
    vec2 e = vec2(0.01, 0);
    vec3 n = d - vec3(
        getDist(p - e.xyy),
        getDist(p - e.yxy),
        getDist(p - e.yyx)
    );
    return normalize(n);
}

vec3 getCameraPosition() {
    float t = iTime * 0.5;
    float radius = 4.0;
    float height = 2.0 * sin(t * 0.5);

    return vec3(
        radius * cos(t),
        height,
        radius * sin(t)
    );
}

mat3 getCameraMatrix(vec3 ro, vec3 lookAt) {
    vec3 ww = normalize(lookAt - ro);
    vec3 uu = normalize(cross(ww, vec3(0.0, 1.0, 0.0)));
    vec3 vv = normalize(cross(uu, ww));
    return mat3(uu, vv, ww);
}

float softShadow(vec3 ro, vec3 rd, float mint, float maxt, float k) {
    float res = 1.0;
    float t = mint;
    for(int i = 0; i < 32; i++) {
        float h = getDist(ro + rd * t);
        if(h < 0.001) return 0.0;
        res = min(res, k * h / t);
        t += clamp(h, 0.01, 0.2);
        if(t > maxt) break;
    }
    return res;
}

float calcAO(vec3 p, vec3 n) {
    float occ = 0.0;
    float sca = 1.0;
    for(int i = 0; i < 5; i++) {
        float h = 0.01 + 0.12 * float(i)/4.0;
        float d = getDist(p + h * n);
        occ += (h - d) * sca;
        sca *= 0.95;
    }
    return clamp(1.0 - 3.0 * occ, 0.0, 1.0);
}

vec3 render(vec3 ro, vec3 rd) {
    vec3 col = vec3(0.0);
    float d = rayMarch(ro, rd);

    if(d < MAX_DIST) {
        vec3 p = ro + rd * d;
        vec3 n = getNormal(p);

        float t = iTime;
        vec3 color1 = vec3(0.5 + 0.5 * sin(t), 0.5 + 0.5 * cos(t), 0.5 + 0.5 * sin(t + 1.0));
        vec3 color2 = vec3(0.5 + 0.5 * cos(t + 2.0), 0.5 + 0.5 * sin(t + 2.0), 0.5 + 0.5 * cos(t));
        vec3 mat = color1 * pattern1(p) + color2 * pattern2(p);

        vec3 lightPos = vec3(2.0 * cos(iTime), 4.0, 2.0 * sin(iTime));
        vec3 lightDir = normalize(lightPos - p);
        vec3 viewDir = normalize(ro - p);
        vec3 reflDir = reflect(-lightDir, n);

        float ao = calcAO(p, n);
        vec3 ambient = 0.2 * mat * ao;

        float diff = max(dot(n, lightDir), 0.0);
        vec3 diffuse = mat * diff;

        float spec = pow(max(dot(reflDir, viewDir), 0.0), 32.0);
        vec3 specular = vec3(0.5) * spec;

        float shadow = softShadow(p, lightDir, 0.02, 2.5, 32.0);
        float fresnel = pow(1.0 + dot(n, viewDir), 5.0);

        col = ambient + (diffuse + specular) * shadow;
        col += 0.1 * fresnel * vec3(1.0);

        float fogFactor = 1.0 - exp(-0.1 * d);
        vec3 fogColor = vec3(0.5, 0.6, 0.7);
        col = mix(col, fogColor, fogFactor);
    }

    return col;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec3 col = vec3(0.0);
    for(int m = 0; m < AA; m++) {
        for(int n = 0; n < AA; n++) {
            vec2 offset = vec2(float(m), float(n)) / float(AA);
            vec2 uv = (fragCoord + offset - 0.5 * iResolution.xy) / iResolution.y;

            vec3 ro = getCameraPosition();
            vec3 lookAt = vec3(0.0, 0.0, 0.0);
            mat3 cam = getCameraMatrix(ro, lookAt);
            vec3 rd = cam * normalize(vec3(uv, 1.5));

            col += render(ro, rd);
        }
    }
    col /= float(AA * AA);
    col = col / (1.0 + col);
    col = pow(col, vec3(0.4545));

    fragColor = vec4(col, 1.0);
}
